import {icons} from './ui-icons.js';
const {disciplines,stages,limaDate,escapeHtml:h,validateSchedule,parseCsv,rowsToActivities,exportCsv,progress}=core;
const URL='https://azajuquqksrjyfbtcujq.supabase.co';
const KEY=__CX360_PUBLISHABLE_KEY__;
const db=createClient(URL,KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});
const $=s=>document.querySelector(s),root=$('#app');
const kinds={activity:'Actividades',schedule:'Cronogramas',system:'Sistemas',document:'Documentos',protocol:'Protocolos',test:'Pruebas',restriction:'Restricciones',instrument:'Instrumentos',om:'O&M',training:'Capacitación',handover:'Entrega y cierre',proposal:'Reprogramaciones',coverage:'Cobertura de avance'};
const roles={admin:'Administrador designado',gp:'Gerente de Proyecto',kp1:'KP1 Supervisión',especialista_anin:'Especialista ANIN',especialista_supervision:'Especialista Supervisión',riesgos:'Riesgos',ssoma:'SSOMA',auditor:'Auditor de lectura'};
const S={member:null,snapshot:null,screen:'home',specialty:'',search:'',busy:false,imported:null,mfa:null,recovery:location.hash.includes('type=recovery'),chat:{messages:[],specialty:'',asking:false,draft:''},kb:null,kbLoading:false,esp:'IIEE',espTab:{},menuOpen:false};
const records=kind=>(S.snapshot?.records||[]).filter(r=>!kind||r.kind===kind);
const get=id=>records().find(r=>r.id===id);
const title=id=>{const r=get(id);return r?`${r.payload.code} · ${r.payload.title}`:'PENDIENTE'};
const button=(label,action,cls='btn')=>`<button type="button" class="${cls}" data-action="${h(action)}">${h(label)}</button>`;
const chip=state=>`<span class="chip ${['CERRADO','ACEPTADO','PUBLICADO','ACEPTADO_CON_EVIDENCIA'].includes(state)?'green':['BLOQUEADO','OBSERVADO','REVOCADO'].includes(state)?'red':'orange'}">${h(state)}</span>`;
const options=(items,value='')=>items.map(([v,label])=>`<option value="${h(v)}" ${String(v)===String(value)?'selected':''}>${h(label)}</option>`).join('');
const ctx=()=>({records,get,h,button,chip,options,canEdit,today:limaDate(),disciplines,S,kinds,tableRow});
function notice(message,error=false){let n=$('#message');if(!n){n=document.createElement('div');n.id='message';n.className='toast';n.setAttribute('role','status');document.body.append(n)}n.textContent=message;n.style.background=error?'#9b2532':'#142d4b';clearTimeout(n.timer);n.timer=setTimeout(()=>n.remove(),9000)}
function chatKey(){return S.member?'cx360-chat-'+S.member.user_id:''}
function saveChat(){try{if(chatKey())sessionStorage.setItem(chatKey(),JSON.stringify({messages:S.chat.messages.filter(m=>!m.pending).slice(-24),specialty:S.chat.specialty}))}catch{}}
function loadChat(){try{const v=JSON.parse(sessionStorage.getItem(chatKey())||'null');if(v&&Array.isArray(v.messages)){S.chat.messages=v.messages;S.chat.specialty=v.specialty||''}}catch{}}
function clearChat(){try{for(const k of Object.keys(sessionStorage))if(k.startsWith('cx360-chat-'))sessionStorage.removeItem(k)}catch{}S.chat={messages:[],specialty:'',asking:false,draft:''};S.kb=null}
function errorMessage(e){console.error(e);const msg=String(e?.message||e);if(/JWT|refresh_token|session.*expired/i.test(msg))return 'La sesión venció. Ingrese nuevamente.';return msg.slice(0,450)}
function field(name,label,value='',type='text',extra=''){return `<label class="label" for="f-${h(name)}">${h(label)}</label>${type==='textarea'?`<textarea id="f-${h(name)}" class="input" name="${h(name)}" ${extra}>${h(value)}</textarea>`:`<input id="f-${h(name)}" class="input" name="${h(name)}" type="${h(type)}" value="${h(value)}" ${extra}>`}`}
function select(name,label,items,value='',extra=''){return `<label class="label" for="f-${h(name)}">${h(label)}</label><select id="f-${h(name)}" class="input" name="${h(name)}" ${extra}>${options(items,value)}</select>`}
function closeModal(){const d=$('#cx-dialog');if(d){d.close();d.remove()}}
function modal(name,html){closeModal();const d=document.createElement('dialog');d.id='cx-dialog';d.className='dialog';d.innerHTML=`<div class="row spread"><h2>${h(name)}</h2>${button('Cerrar','close','btn ghost')}</div>${html}`;document.body.append(d);d.showModal();d.addEventListener('close',()=>d.remove());d.querySelector('input,select,textarea,button')?.focus()}
function login(note=''){
 root.innerHTML=`<main class="center"><section class="panel narrow"><img src="./assets/logo-anin.png" class="brandlogo" alt="ANIN"><div class="eyebrow">Hospital de contingencia</div><h1>IREN Sur CX360</h1><p>Control del comisionamiento</p><p class="notice">Piloto privado. Las fechas no liberan pruebas ni autorizan energización.</p>${note?`<p role="alert" class="notice error">${h(note)}</p>`:''}<form id="login">${field('email','Correo autorizado','','email','required autocomplete="username"')}${field('password','Contraseña','','password','required minlength="12" autocomplete="current-password"')}<div class="btnrow"><button class="btn">Ingresar</button>${button('Recuperar acceso','recover','btn ghost')}</div></form><details><summary>Primera activación del administrador</summary><p class="small">Exclusiva para jose.zena.p@uni.pe. Establezca su contraseña y confirme el mensaje recibido en ese correo. La designación no evita la verificación de identidad.</p><form id="activate">${field('password','Nueva contraseña','','password','required minlength="12" autocomplete="new-password"')}<div class="btnrow"><button class="btn">Activar mi acceso</button></div></form></details><p class="small muted">Sin invitaciones automáticas. Uso con conexión a internet; no hay captura offline.</p></section></main>`;
}
async function load(){
 S.snapshot=null;
 const {data:{user},error}=await db.auth.getUser();if(error||!user)throw Error('Ingrese con una sesión válida');
 let {data:member,error:me}=await db.from('cx_members').select('*').eq('user_id',user.id).eq('active',true).maybeSingle();
 if(me)throw me;
 if(!member&&user.email?.toLowerCase()==='jose.zena.p@uni.pe'){const result=await db.rpc('cx_bootstrap_admin');if(result.error)throw result.error;member=result.data;}
 if(!member?.active){S.member=null;S.snapshot=null;throw Error('Cuenta sin membresía activa. La nómina debe ser autorizada por el administrador.')}
 const result=await db.rpc('cx_snapshot');if(result.error){S.snapshot=null;throw result.error}const changed=S.member?.user_id!==member.user_id;S.member=member;S.snapshot=result.data;if(changed){S.chat={messages:[],specialty:'',asking:false,draft:''};S.kb=null;loadChat();}
 S.catalog=null;if(['admin','gp','kp1'].includes(member.role)){const cs=await db.rpc('cx_catalog_status');if(!cs.error)S.catalog=cs.data;}
}
function filtered(kind){return records(kind).filter(r=>(!S.specialty||r.specialty===S.specialty)&&(!S.search||`${r.payload.code} ${r.payload.title} ${r.payload.equipment_tag||''}`.toLowerCase().includes(S.search.toLowerCase())))}
function canEdit(r){return S.member&&S.member.role!=='auditor'&&(['admin','gp','kp1'].includes(S.member.role)||(r.specialty===S.member.specialty&&r.assigned_to===S.member.user_id))}
function catalogLine(r){const p=r.payload,f=ui.fmt;let t='';if(r.kind==='test'&&p.level)t=`Nivel ${p.level} · ${p.witness||''}${p.planned_start?' · Prueba '+f(p.planned_start):''}${p.aconex_notice_by?' · Aviso ACONEX ≤ '+f(p.aconex_notice_by):''}${p.protocol_code?' · '+p.protocol_code:''}`;else if(r.kind==='restriction'&&p.type)t=`${p.type}${p.due_date?' · fecha '+f(p.due_date):''}${p.plan_status?' · '+p.plan_status:''}`;else if(r.kind==='protocol'&&p.fields){const st=pc.protocolStats(r);t=`${st.fields} campos · ${st.pending?st.pending+' criterios POR FIJAR':'criterios con valor'}${p.package?' · Paquete '+p.package:''}${p.level?' · '+p.level+' '+(p.witness||''):''}`}else if(r.kind==='system'&&p.leader_support)t=`${p.leader_support} · Sectores ${p.sectors||'—'}`;else if(r.kind==='document'&&p.planned_submit)t=`Presentación ${f(p.planned_submit)}${p.planned_response?' · Respuesta '+f(p.planned_response):''}`;else if(['training','om'].includes(r.kind)&&p.planned_start)t=`Programado ${f(p.planned_start)}${p.planned_finish&&p.planned_finish!==p.planned_start?' → '+f(p.planned_finish):''}`;return t?`<small class="catline">${h(t)}</small>`:''}
function tableRow(r){const p=r.payload;const files=(S.snapshot.files||[]).filter(f=>f.record_id===r.id);const frozen=['CERRADO','ACEPTADO','PUBLICADO','ACEPTADO_CON_EVIDENCIA','REVOCADO','ARCHIVADO'].includes(r.state);return `<article class="listitem"><div class="row spread"><strong>${h(p.code)} · ${h(p.title)}</strong>${chip(r.state)}</div><small>${h(disciplines[r.specialty]||'Multidisciplinario')} · ${h(p.stage||kinds[r.kind])} · Revisión: ${h(p.revision||'PENDIENTE')}</small><small>Sistema: ${h(p.system_code||'PENDIENTE')} · Equipo/TAG: ${h(p.equipment_tag||'PENDIENTE')}</small>${r.kind==='activity'?`<small>Fecha de origen: ${h(p.planned_start||'PENDIENTE')} → ${h(p.planned_finish||'PENDIENTE')} · Real: ${h(p.actual_start||'PENDIENTE')} → ${h(p.actual_finish||'PENDIENTE')}</small>`:''}${catalogLine(r)}<small>Responsable: ${h((S.snapshot.members||[]).find(m=>m.user_id===r.assigned_to)?.full_name||p.responsible||p.owner||'PENDIENTE')} · Versión de registro: ${r.version}</small>${p.next_action?`<p>${h(p.next_action)}</p>`:''}<div class="btnrow">${button('Ver / revisar','edit:'+r.id,'btn ghost')}${!frozen&&canEdit(r)?button('Adjuntar evidencia','upload:'+r.id,'btn ghost'):''}${files.map(f=>button(f.name,'file:'+f.id,'btn ghost')).join('')}${r.kind==='protocol'?button('Protocolo en blanco','print-protocol:'+r.id,'btn ghost'):''}${r.kind==='test'&&get(p.protocol_id)?button('Imprimir registro','print-test:'+r.id,'btn ghost'):''}${r.kind==='test'&&String(p.witness||'').startsWith('HP')&&canEdit(r)&&!frozen?button(p.aconex_notice_ref?'Aviso ACONEX ✓':'Registrar aviso ACONEX','notice:'+r.id,'btn ghost'):''}${r.kind==='protocol'&&r.state==='PUBLICADO'?button('Preparar prueba','test:'+r.id):''}${r.kind==='schedule'&&r.state==='ACEPTADO_CON_EVIDENCIA'&&S.member.role==='gp'?button('Registrar vigencia formal','current:'+r.id):''}${!['REVOCADO','ARCHIVADO'].includes(r.state)&&['admin','gp','kp1'].includes(S.member.role)?button('Revocar','revoke:'+r.id,'btn danger'):''}</div></article>`}
function home(){const acts=records('activity'),today=limaDate(),due=acts.filter(a=>a.payload.planned_finish&&a.payload.planned_finish<today),agenda=acts.filter(a=>a.payload.planned_start<=today&&a.payload.planned_finish>=today);const metric=progress(records(),limaDate(),S.snapshot.settings?.current_schedule);const settings=S.snapshot.settings;const current=get(settings?.current_schedule);return `<h2>Control de hoy</h2><p class="muted">Corte de consulta: ${h(new Intl.DateTimeFormat('es-PE',{timeZone:'America/Lima',dateStyle:'short',timeStyle:'medium'}).format(new Date(S.snapshot.cut)))} · America/Lima</p><div class="notice"><strong>${current?'REVISIÓN VIGENTE REGISTRADA: '+h(current.payload.code)+' / '+h(current.payload.revision):'PLANIFICACIÓN PROVISIONAL / CRONOGRAMA NO ACREDITADO'}</strong><p>Programación, ejecución reportada, verificación y aceptación se controlan por separado. La fecha no libera la prueba.</p></div><h3 class="tiles-title">Especialidades</h3>${sui.specialtyTiles(ctx())}<div class="grid kpis"><div class="kpi">Actividades visibles<div class="num">${acts.length||'NO DISPONIBLE'}</div><div class="hint">Universo según permisos de la cuenta</div></div><div class="kpi">Fecha de origen vencida<div class="num">${acts.length?due.length:'NO DISPONIBLE'}</div><div class="hint">No acredita incumplimiento contractual</div></div><div class="kpi">Pruebas con cierre independiente<div class="num">${records('test').length?records('test').filter(t=>t.state==='CERRADO').length:'NO DISPONIBLE'}</div><div class="hint">No equivale a aceptación de toda la actividad</div></div><div class="kpi">Avance verificable<div class="num metric">${h(metric.label)}</div><div class="hint">Numerador: ${metric.numerator??'NO DISPONIBLE'} · Denominador: ${metric.denominator??'NO DISPONIBLE'} · Revisión: ${h(metric.revision||'NO ACREDITADA')}</div></div></div><p class="small muted">${h(metric.reason)}. No se suman vencidas, bloqueadas y ejecutadas como categorías excluyentes.</p><div class="section panel"><h3>Agenda de hoy</h3>${agenda.length?agenda.map(tableRow).join(''):'Agenda NO DISPONIBLE en los registros consultados.'}</div><div class="section panel"><h3>Restricciones e interferencias abiertas</h3>${records('restriction').filter(r=>!['CERRADO','REVOCADO'].includes(r.state)).map(tableRow).join('')||'NO DISPONIBLES en los registros consultados.'}</div><div class="section panel"><h3>Vencidas según fecha de origen</h3>${due.map(tableRow).join('')||'Sin vencidas identificables; no acredita ausencia de atrasos.'}</div>`}
function list(kind){const rs=filtered(kind);return `<div class="row spread"><h2>${h(kinds[kind])}</h2>${S.member.role!=='auditor'?button(kind==='schedule'?'Importar a revisión':'Nuevo registro',kind==='schedule'?'import':'new:'+kind):''}</div>${kind==='schedule'?'<p class="notice">Conservar por separado línea base original, revisión aceptada vigente, propuestas y fechas reales. Las importaciones se guardan como BORRADOR.</p>':''}${kind==='test'?'<p class="notice">Sin protocolo publicado, fuente aceptada vigente, instrumentos y SSOMA comprobados, no se registra ejecución. La revisión independiente se exige en servidor.</p>':''}<div class="filterbar"><label>Disciplina<select class="input" id="discipline-filter">${options([['','Todas las autorizadas'],...Object.entries(disciplines)],S.specialty)}</select></label><label>Buscar código, título o TAG<input class="input" id="search" value="${h(S.search)}"></label>${button('Buscar','search','btn ghost')}</div><div class="panel">${rs.map(tableRow).join('')||'<p class="empty">Sin registros disponibles. No se infiere avance.</p>'}</div>`}
function settings(){const m=S.member,c=S.snapshot.settings;return `<h2>Administración y seguridad</h2><div class="panel"><h3>${h(m.full_name)}</h3><p>${h(m.email)} · ${h(roles[m.role])}</p><div class="btnrow">${button('Cambiar contraseña','password')}${button('Configurar / verificar MFA','mfa','btn ghost')}${button('Cerrar sesión','logout','btn danger')}</div></div>${ui.catalogPanel(ctx())}${aui.assistantAdminPanel(ctx())}<div class="section panel"><h3>Custodia documental</h3><p>${c?.custody_authorized?'Referencia registrada: '+h(c.custody_reference):'PENDIENTE: no se habilita cargar documentación real sin registrar la autorización institucional aplicable.'}</p>${m.role==='admin'&&!c?.custody_authorized?button('Registrar autorización de custodia','custody'):''}</div><div class="section panel"><h3>Profesionales registrados</h3>${m.role==='admin'?button('Invitar profesional nominal','invite'):''}${S.snapshot.members.map(x=>`<p>${h(x.full_name)} · ${h(roles[x.role])} · ${h(x.specialty||'General')} · ${x.active?'ACTIVO':'INACTIVO'} ${m.role==='admin'&&x.user_id!==m.user_id?button(x.active?'Revocar acceso':'Reactivar acceso','member:'+x.user_id+':'+(!x.active),'btn ghost'):''}</p>`).join('')}<p class="small muted">La nómina adicional está pendiente. No se crean integrantes ni se envían invitaciones automáticamente.</p></div><div class="section panel"><h3>Continuidad y respaldo de consulta</h3><p>Exporta un archivo local con los registros visibles, historial reciente y huella SHA-256. No incluye archivos adjuntos. Consérvalo en un repositorio institucional autorizado.</p>${button('Exportar respaldo de consulta','backup')}${button('Verificar respaldo local','checkbackup','btn ghost')}<p class="small muted">La recuperación completa de base de datos y archivos requiere el procedimiento de administración; esta exportación no sustituye un respaldo integral.</p></div>`}
function audit(){return `<h2>Historial y trazabilidad</h2><p>Últimos 200 eventos visibles. La auditoría se genera en servidor y no puede editarse desde la aplicación.</p><div class="panel">${S.snapshot.events.map(e=>`<details class="listitem"><summary>${h(e.at)} · ${h(e.action)} · ${h(title(e.record_id))}</summary><p>Actor: ${h(S.snapshot.members.find(m=>m.user_id===e.actor)?.full_name||e.actor||'Servicio de administración')}</p><pre>${h(JSON.stringify({antes:e.before_value,despues:e.after_value},null,2))}</pre></details>`).join('')||'Sin eventos visibles.'}</div>`}
const NAV_GROUPS=()=>[['General',[['home','Hoy',icons.home],['asistente','Asistente Cx',icons.chat]]],['Especialidades',Object.keys(sc.SPECS).map(k=>['esp:'+k,sc.SPECS[k].nav||sc.SPECS[k].name,k])],['Control',[['plan','Plan Cx',icons.plan],['followup','Seguimiento',icons.bell]]],['Registros',Object.entries(kinds).map(([k,t])=>[k,t,icons.list])],['Sistema',[['audit','Historial',icons.clock],['settings','Administración',icons.gear]]]];
const STRIP=()=>[['home','Hoy'],['asistente','Asistente Cx'],...Object.keys(sc.SPECS).map(k=>['esp:'+k,sc.SPECS[k].short,k]),['plan','Plan Cx'],['followup','Seguimiento']];
function screenLabel(){if(S.screen.startsWith('esp:'))return sc.SPECS[S.screen.slice(4)]?.name||'Especialidad';for(const [,items] of NAV_GROUPS())for(const [k,t] of items)if(k===S.screen)return t;return 'IREN Sur CX360'}
function navItem([k,t,ic]){const on=S.screen===k;const mark=sc.SPECS[ic]?`<span class="sbadge tone-${sc.SPECS[ic].tone}">${icons[ic]}<b>${ic}</b></span>`:ic||'';return `<button type="button" class="navitem${on?' on':''}" data-nav="${h(k)}" ${on?'aria-current="page"':''}>${mark}<span>${h(t)}</span></button>`}
function render(){if(S.member&&!S.snapshot){root.innerHTML='<main class="center"><section class="panel narrow"><h1>Consulta no disponible</h1><p>No se muestran datos ni indicadores anteriores hasta recuperar la conexión y comprobar los permisos.</p>'+button('Reintentar','refresh')+' '+button('Cerrar sesión','logout','btn ghost')+'</section></main>';return}if(!S.member||!S.snapshot)return login();
 if(S.screen.startsWith('esp:')){S.esp=S.screen.slice(4);if(!sc.SPECS[S.esp]){S.screen='home'}}
 const screen=S.screen==='home'?home():S.screen==='asistente'?aui.assistantScreen(ctx()):S.screen.startsWith('esp:')?sui.specialtyScreen(ctx()):S.screen==='plan'?ui.planScreen(ctx()):S.screen==='followup'?ui.followupScreen(ctx()):S.screen==='settings'?settings():S.screen==='audit'?audit():list(S.screen);
 root.innerHTML=`<div class="app${S.menuOpen?' menu-open':''}"><aside class="side" aria-label="Navegación principal"><div class="side-brand"><img src="./assets/logo-anin.png" alt="ANIN"><div><strong>IREN Sur CX360</strong><span>Comisionamiento de la contingencia</span></div><button type="button" class="iconbtn side-close" data-action="menu" aria-label="Cerrar menú">${icons.close}</button></div><nav class="side-nav">${NAV_GROUPS().map(([g,items])=>`<p class="side-group">${h(g)}</p>${items.map(navItem).join('')}`).join('')}</nav><div class="side-user"><strong>${h(S.member.full_name)}</strong><span>${h(roles[S.member.role])}${S.member.specialty?', '+h(S.member.specialty):''}</span></div></aside><div class="scrim" data-action="menu"></div>
 <div class="main"><header class="top"><button type="button" class="iconbtn menu-btn" data-action="menu" aria-label="Menú">${icons.menu}</button><div class="top-title"><span>Piloto privado ANIN</span><strong>${h(screenLabel())}</strong></div><div class="top-actions"><span class="net ${navigator.onLine?'on':'off'}" title="${navigator.onLine?'Cambios con confirmación del servidor':'Registro suspendido; no hay sincronización sin conexión'}">${navigator.onLine?'En línea':'Sin conexión'}</span><button type="button" class="iconbtn" data-action="refresh" aria-label="Actualizar" title="Actualizar">${icons.refresh}</button><button type="button" class="iconbtn" data-action="report" aria-label="Reporte" title="Reporte del corte">${icons.report}</button></div></header>
 <nav class="strip" aria-label="Accesos rápidos">${STRIP().map(([k,t,sp])=>`<button type="button" class="stripbtn${S.screen===k?' on':''}${sp?' tone-'+sc.SPECS[sp].tone:''}" data-nav="${h(k)}">${sp?`<i class="dot"></i>`:''}${h(t)}</button>`).join('')}</nav>
 <main class="content" id="content">${screen}<p class="small muted foot">Ningún registro equivale a firma digital legal ni remisión Aconex/ACC. Revisión técnica, verificación y aceptación deben acreditarse por separado.</p></main></div>
 ${S.screen!=='asistente'?'<button type="button" class="fab" data-nav="asistente" aria-label="Abrir el Asistente Cx" title="Asistente Cx">?</button>':''}</div>`;afterRender();}
function afterRender(){if(S.screen==='asistente'){if(!S.kb&&!S.kbLoading)loadKb();const log=$('#chat-log');if(log)log.scrollTop=log.scrollHeight;}if(S.screen==='settings'&&S.member?.role==='admin'&&!S.kb&&!S.kbLoading)loadKb(()=>{if(S.screen==='settings')render()});}
async function callAssistant(payload){const {data:{session}}=await db.auth.getSession();if(!session)throw Error('La sesión venció. Ingrese nuevamente.');const r=await fetch(URL+'/functions/v1/cx360-asistente',{method:'POST',headers:{Authorization:'Bearer '+session.access_token,apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify(payload)});const out=await r.json().catch(()=>({}));if(!r.ok)throw Object.assign(Error(out.error||'Servicio del asistente no disponible'),{status:r.status});return out}
async function loadKb(done){S.kbLoading=true;try{S.kb=await callAssistant({action:'status'})}catch(e){try{const st=await db.rpc('cx_kb_status');S.kb=st.error?{error:'Asistente no disponible: '+errorMessage(st.error)}:{...st.data,ai:false}}catch(e2){S.kb={error:'Asistente no disponible: '+errorMessage(e2)}}}finally{S.kbLoading=false;const el=$('#kb-status');if(el)el.innerHTML=aui.statusLine(ctx());if(done)done()}if(S.kb&&!S.kb.error&&!S.kb.glossary){try{const g=await db.rpc('cx_kb_glossary');if(!g.error&&Array.isArray(g.data)){S.kb.glossary=g.data;if(S.screen==='asistente'&&!$('details.glossary')){const d=$('details.section');if(d)d.insertAdjacentHTML('beforebegin',aui.glossaryPanel(ctx()))}}}catch{}}}
function refreshChat(){const log=$('#chat-log');if(!log)return;log.innerHTML=aui.chatLogHtml(ctx());log.scrollTop=log.scrollHeight;const st=$('#kb-status');if(st)st.innerHTML=aui.statusLine(ctx());const b=$('#ask-form button[type="submit"]');if(b){b.disabled=S.chat.asking;b.textContent=S.chat.asking?'Consultando…':'Consultar'}}
async function ask(text){
 const v=ac.validQuestion(text);if(!v.ok)return notice(v.error,true);if(S.chat.asking)return;if(!navigator.onLine)return notice('Sin conexión. El asistente requiere internet.',true);
 const history=ac.buildHistory(S.chat.messages),id=crypto.randomUUID().slice(0,8),specialty=S.chat.specialty||null;
 S.chat.messages.push({role:'user',id:'u'+id,content:v.text},{role:'assistant',id:'a'+id,pending:true});S.chat.asking=true;S.chat.draft='';const q=$('#f-question');if(q)q.value='';refreshChat();
 let msg;
 try{const out=await callAssistant({question:v.text,specialty,history});msg={mode:out.mode,answer:out.answer||null,notice:out.notice||null,sources:out.sources||[],truncated:Boolean(out.truncated)};if(S.kb&&!S.kb.error){S.kb.used_today=out.used;S.kb.daily_limit=out.limit}}
 catch(e){if([400,403,429].includes(e.status))msg={error:errorMessage(e)};else{try{const r=await db.rpc('cx_kb_search',{p_query:v.text,p_limit:8,p_specialty:specialty||S.member?.specialty||null});msg=r.error?{error:errorMessage(r.error)}:{mode:'documental',answer:null,notice:'No se pudo contactar al servicio del asistente; se muestran los fragmentos encontrados en la base documental.',sources:(r.data||[]).map((s,i)=>({...s,n:i+1}))}}catch(e2){msg={error:errorMessage(e2)}}}}
 const target=S.chat.messages.find(m=>m.id==='a'+id);if(target)Object.assign(target,{pending:false,at:new Date().toISOString()},msg);
 S.chat.asking=false;saveChat();refreshChat();
}
function chatSource(msgId,n){const m=S.chat.messages.find(x=>x.id===msgId);return {m,s:m?.sources?.find(x=>String(x.n)===String(n))}}
